const crypto = require('crypto');
const item = $input.first();
const headers = item.json.headers || {};
const rawBody = item.json.body;
if (typeof rawBody !== 'string') throw new Error('Raw Body must be enabled on the Webhook node');
const timestamp = String(headers['x-automation-timestamp'] || '');
const received = String(headers['x-automation-signature'] || '');
const secret = process.env.N8N_W8_ACCOUNT_SECRET || '';
if (secret.length < 32 || !/^\d{10}$/.test(timestamp) || !/^[a-f0-9]{64}$/i.test(received)) throw new Error('Invalid webhook configuration');
if (Math.abs(Math.floor(Date.now() / 1000) - Number(timestamp)) > 300) throw new Error('Expired webhook signature');
const expected = crypto.createHmac('sha256', secret).update(`${timestamp}.${rawBody}`).digest('hex');
const a = Buffer.from(received, 'hex');
const b = Buffer.from(expected, 'hex');
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) throw new Error('Invalid webhook signature');
const payload = JSON.parse(rawBody);
const escapeHtml = value => String(value).replace(/[&<>"']/g, character => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[character]);
const validEmail = value => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(value || ''));
const validDate = value => typeof value === 'string' && Number.isFinite(Date.parse(value));
const exactKeys = expectedKeys => Object.keys(payload).sort().join(',') === expectedKeys.slice().sort().join(',');
const makeMail = (from, to, subject, title, message, extra = '') => ({ json: { from, to, subject, html: `<div style="font-family:Arial,sans-serif;max-width:520px;margin:auto;padding:24px;border:1px solid #e2e8f0;border-radius:12px"><h2 style="color:#0f172a">${title}</h2><p style="color:#475569">${message}</p>${extra}<p style="color:#64748b;font-size:13px">Si no realizaste esta acción, comunícate con el administrador de tu cuenta.</p></div>` } });
if (payload.evento === 'mfa.email.change.code') {
  if (!exactKeys(['evento', 'email', 'token_mfa', 'timestamp', 'vigencia_segundos']) || !validEmail(payload.email) || !/^\d{6}$/.test(String(payload.token_mfa || '')) || !validDate(payload.timestamp) || !Number.isInteger(payload.vigencia_segundos) || payload.vigencia_segundos < 1 || payload.vigencia_segundos > 300) throw new Error('Invalid email change code event');
  const edad = Date.now() - Date.parse(payload.timestamp);
  if (edad < -60000 || edad > payload.vigencia_segundos * 1000) throw new Error('Expired email change code');
  const minutos = Math.max(1, Math.ceil((payload.vigencia_segundos * 1000 - Math.max(0, edad)) / 60000));
  const codigo = escapeHtml(payload.token_mfa);
  const extra = `<p style="font-size:34px;letter-spacing:8px;font-weight:700;text-align:center;margin:24px 0;color:#0d4f9c">${codigo}</p><p>El código vence en ${minutos} minutos. No lo compartas con nadie.</p>`;
  return [makeMail(process.env.MFA_FROM_EMAIL || '', payload.email, 'Confirma el cambio de correo', 'Código para cambiar tu correo', 'Ingresa este código en el sitio para confirmar el nuevo correo.', extra)];
}
if (payload.evento === 'security.notice') {
  if (!exactKeys(['evento', 'email', 'tipo', 'timestamp']) || !validEmail(payload.email) || !validDate(payload.timestamp) || !['correo_cambiado', 'password_cambiada'].includes(payload.tipo)) throw new Error('Invalid security notice event');
  const cambioCorreo = payload.tipo === 'correo_cambiado';
  const title = cambioCorreo ? 'Correo actualizado' : 'Contraseña actualizada';
  const message = cambioCorreo ? 'Se confirmó un cambio de correo en tu cuenta.' : 'Se cambió la contraseña de tu cuenta.';
  return [makeMail(process.env.MFA_FROM_EMAIL || '', payload.email, title, title, message)];
}
if (payload.evento === 'admin.solicitud_cuenta') {
  if (!exactKeys(['evento', 'solicitud_id', 'tipo', 'timestamp']) || !Number.isSafeInteger(payload.solicitud_id) || payload.solicitud_id < 1 || !['nit', 'nombreUnidad', 'eliminacion', 'correccion'].includes(payload.tipo) || !validDate(payload.timestamp)) throw new Error('Invalid account request event');
  const tipos = { nit: 'actualización de NIT', nombreUnidad: 'actualización del nombre de unidad', eliminacion: 'solicitud de eliminación', correccion: 'solicitud de corrección' };
  const from = process.env.ADMIN_ALERT_FROM || '';
  const to = process.env.ADMIN_ALERT_TO || '';
  if (!validEmail(from) || !validEmail(to)) throw new Error('Admin email configuration is invalid');
  return [makeMail(from, to, 'Nueva solicitud de cuenta', 'Solicitud de cuenta pendiente', `Hay una solicitud de tipo ${tipos[payload.tipo]}.`, `<p>Solicitud ID: ${payload.solicitud_id}</p><p>Revisa los detalles en el panel administrativo.</p>`)];
}
throw new Error('Event not allowed');
